


export type TippingSettings = { "default_enabled"?: boolean; /** The preselected fixed tip. Its amount and currency must match one of the effective smart_tip_money_options. Null means no preselection is set at this scope; effective settings may inherit a preselection from a parent scope. */ "default_smart_tip_money": ((({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; })) | (null) | (unknown)); /** The preselected tip percent, from 1 through 100 with at most four decimal places. It must match one of the effective tip_percent_options. Null means no preselection is set at this scope; effective settings may inherit a preselection from a parent scope. minimum: 1. maximum: 100. multipleOf: 0.0001. */ "default_tip_percent": number | null; "is_custom_tip_enabled"?: boolean; "is_smart_tips_enabled"?: boolean; /** minItems: 3. maxItems: 3. */ "smart_tip_money_options"?: Array<({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; })>; /** Three tip percents to offer, each from 1 through 100 with at most four decimal places. minItems: 3. maxItems: 3. */ "tip_percent_options"?: Array<number>; };
